function patternNumberGrid(n) {
  let rows = [];
  const len = 2 * n - 1;
  for (let r = 0; r < len; r++) {
    let row = '';
    for (let c = 0; c < len; c++) {
      const top = r;
      const left = c;
      const bottom = len - 1 - r;
      const right = len - 1 - c;
      const val = n - Math.min(top, left, bottom, right);
      row += val;
    }
    rows.push(row);
  }
  return rows.join('\n');
}

