function patternNumberGrid(n) {
  let rows = [];
  const len = 2 * n - 1;
  for (let r = 0; r < len; r++) {
    let row = '';
    for (let c = 0; c < len; c++) {
      row += (n - Math.min(r, c, len - 1 - r, len - 1 - c));
    }
    rows.push(row);
  }
  return rows.join('\n');
}
